<script setup lang="ts">
import {Head,Link,useForm,router} from '@inertiajs/vue3';import Workspace from '@/Layouts/Workspace.vue';import {ref} from 'vue';
const props=defineProps<{product:any;workspace:any;module:string;definition:any;records:any;role:string}>();
const initial:Record<string,any>={};for(const [key,type] of Object.entries(props.definition.fields)) if(!['status','ai_mode'].includes(key))initial[key]=type==='boolean'?true:'';
if(props.module==='workflows')initial.graph=JSON.stringify({nodes:[{id:'start',type:'manual'},{id:'finish',type:'end'}],edges:[{source:'start',target:'finish'}]},null,2);
if(props.module==='journal_entries')initial.lines=JSON.stringify([{account_id:1,debit_minor:100,credit_minor:0},{account_id:2,debit_minor:0,credit_minor:100}],null,2);
const form=useForm(initial);const open=ref(false);const search=ref('');const base=`/app/${props.workspace.slug}/${props.module}`;
const label=(s:string)=>s.replaceAll('_',' ');
</script><template><Head :title="definition.label"/><Workspace :product="product" :workspace="workspace"><p class="eyebrow">WORKSPACE / {{definition.label}}</p><div class="page-title"><h1>{{definition.label}}</h1><button v-if="!definition.readonly && role!=='viewer'" @click="open=!open">{{open?'Close form':'+ New record'}}</button></div><form class="search" @submit.prevent="router.get(base,{search},{preserveState:true})" v-if="definition.fields.name"><input v-model="search" placeholder="Search by name" aria-label="Search by name"/><button class="secondary">Search</button></form><form v-if="open" class="panel form-panel" @submit.prevent="form.post(base,{onSuccess:()=>{form.reset();open=false;}})"><h2>New {{definition.label.toLowerCase()}} record</h2><label v-for="(value,key) in initial" :key="key">{{label(key)}}<textarea v-if="['text','json'].includes(definition.fields[key])" v-model="form[key]" rows="6" required/><input v-else-if="definition.fields[key]==='boolean'" type="checkbox" v-model="form[key]"/><input v-else v-model="form[key]" :type="definition.fields[key]==='integer'?'number':definition.fields[key]==='date'?'date':key==='email'?'email':'text'" :min="definition.fields[key]==='integer'?1:undefined" required/><span class="error" v-if="form.errors[key]">{{form.errors[key]}}</span></label><button :disabled="form.processing">Save record</button></form><section class="panel table-panel"><table><thead><tr><th>ID</th><th v-for="(_,key) in definition.fields" :key="key">{{label(String(key))}}</th><th></th></tr></thead><tbody><tr v-for="record in records.data" :key="record.id"><td>#{{record.id}}</td><td v-for="(type,key) in definition.fields" :key="key"><span :class="{badge:key==='status'}">{{type==='json'?'Structured data':String(record[key]??'—').slice(0,100)}}</span></td><td><Link :href="`${base}/${record.id}`" class="text-link">Open →</Link></td></tr></tbody></table><div class="empty" v-if="!records.data.length"><h2>No records yet</h2><p class="muted">{{definition.readonly?'Records appear here when you complete the related workflow.':'Create the first record to get started.'}}</p></div></section><nav class="pagination"><Link v-if="records.prev_page_url" :href="records.prev_page_url">← Previous</Link><span>Page {{records.current_page}} of {{records.last_page}} · {{records.total}} records</span><Link v-if="records.next_page_url" :href="records.next_page_url">Next →</Link></nav></Workspace></template>
